import { Group, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Position from config (adapter will also apply scenePosition, so we only set local offset if needed)
  if (config.position) {
    group.position.set(config.position.x || 0, config.position.y || 0, config.position.z || 0);
  }
  if (config.rotation) {
    group.rotation.set(config.rotation.x || 0, config.rotation.y || 0, config.rotation.z || 0);
  }
  if (config.scale) {
    group.scale.set(config.scale.x || 1, config.scale.y || 1, config.scale.z || 1);
  }

  // Atlas region defines full texture (0,0,512,512 -> no UV offset)
  const aspect = 1; // square
  const geo = new PlaneGeometry(1, 1);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // Load texture asynchronously (will be applied when ready)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
      tex.needsUpdate = true;
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  const mesh = new ctx.THREE.Mesh(geo, mat);
  group.add(mesh);

  // Static composition: no interactivity, no event handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geo.dispose();
    mat.dispose();
    // Texture is cached and should not be disposed here
  };

  return group;
}
